import gulp from 'gulp';
import gtb from './gtb';
import pkg from './package.json';
import commonTasks from './gtb/common-tasks';
import serve from './gulp-tasks/serve';

var task = gtb();
// gtb implicitly outputs all the files to `dest` unless
// they have already been written with `put()`.
// Default value:
task.config({
  dest: 'dist'
});

task.filesIn('app')
  .withExtension('js')
  .excluding(/^nobabel\//)
  .run(commonTasks.babel({
    presets: ['es2015'],
    plugins: ['transform-es2015-modules-amd']
  }))
  .run(commonTasks.minifyJs());
task.filesIn('app')
  .withExtension('js')
  .matching(/^nobabel\//)
  .run(commonTasks.minifyJs());
task.filesIn('app')
  .withExtension('sass', 'scss')
  .run(commonTasks.compileSass())
  .run(commonTasks.autoprefixer())
  .run(commonTasks.minifyCss());
task.filesIn('app')
  .withExtension('css')
  .run(commonTasks.autoprefixer())
  .run(commonTasks.minifyCss());
task.filesIn('app')
  .withExtension('html')
  .run(commonTasks.replace('{{_!_version_!_}}', pkg.version))
  .run(commonTasks.minifyHtml())
task.filesIn('app')
  .withExtension('jpeg', 'jpg', 'png', 'svg')
  .run(commonTasks.imagemin());
task.filesIn('bower_components')
  .inFolder('moment/min')
  .withName('moment.min.js')
  .run(commonTasks.minifyJs())
  .put('vendor/moment');

gulp.task('build', task.build());
gulp.task('default', gulp.series('build'));
gulp.task('serve', gulp.series('build', serve));

var minifyCss = require('gulp-cssnano');
var minifyHtml = require('gulp-htmlmin');
var minifyInline = require('gulp-minify-inline');
var uglify = require('gulp-uglify');
var sass = require('gulp-sass');
var babel = require('gulp-babel');
var autoprefixer = require('gulp-autoprefixer');
var replace = require('gulp-replace');
var imagemin = require('gulp-imagemin');
var through = require('through2')
var streamCombiner = require('stream-combiner');

module.exports = {
  compileSass: function(opts) {
    return function() {
      return sass(opts);
    };
  },
  autoprefixer: function(opts) {
    return function() {
      return autoprefixer(opts);
    };
  },
  minifyCss: function(opts) {
    return function() {
      return minifyCss(opts);
    };
  },
  minifyJs: function(opts) {
    return function() {
      return uglify(opts);
    };
  },
  minifyHtml: function(opts) {
    if(typeof opts === 'undefined') {
      opts = {};
    }
    return function() {
      return streamCombiner(
        minifyHtml(opts.html || {
          minifyCSS: true,
          minifyJS: true,
          removeScriptTypeAttributes: true,
          collapseBooleanAttributes: true,
          removeTagWhitespace: true,
          collapseWhitespace: true,
          removeComments: true
        }),
        minifyInline(opts.inline || {})
      );
    };
  },
  imagemin: function(opts) {
    return function() {
      return imagemin(opts);
    };
  },
  babel: function(opts) {
    return function() {
      return babel(opts);
    };
  },
  replace: function(needle, haystack) {
    return function() {
      return replace(needle, haystack);
    };
  },
  log: function(prefix) {
    return function() {
      return through.obj(function(file, enc, cb) {
        console.log(prefix+':', file.relative, '(' + file.path + ')');
        cb(null, file);
      });
    };
  }
};

var gulp = require('gulp');
var through = require('through2');
var merge = require('merge-stream');
var path = require('path');

var defaultConfig = {
  destDir: 'dist'
};

function FileOperationCollection(path) {
  this.steps = [function() {
    return gulp.src(path + '/**/*', {dot: true});
  }];
}

FileOperationCollection.prototype.filter = function(filterFunc) {
  this.steps.push(function(stream) {
    return stream.pipe(through.obj(function(file, enc, cb) {
      if(filterFunc.call(this, file)) {
        cb(null, file);
        return;
      }
      cb(null);
    }.bind(this)));
  });
  return this;
};

FileOperationCollection.prototype.withExtension = function() {
  var exts = Array.prototype.map.call(arguments, function(ext) {
    return '.' + ext;
  });

  return this.filter(function(file) {
    var fileExt = path.extname(file.path)
    return exts.map(function(ext) {
      return fileExt === ext;
    }).indexOf(true) !== -1;
  });
};

FileOperationCollection.prototype.withName = function(name) {
  this.filter(function(file) {
    return path.basename(file.path) === name;
  });
  return this;
};

FileOperationCollection.prototype.matching = function(regexp) {
  return this.filter(function(file) {
    return regexp.test(file.relative);
  });
};

FileOperationCollection.prototype.excluding = function(regexp) {
  return this.filter(function(file) {
    return !regexp.test(file.relative);
  });
};

FileOperationCollection.prototype.inFolder = function(name) {
  return this.filter(function(file) {
    var doesMatch = file.relative.startsWith(name);
    if(doesMatch) {
      file.base = path.join(file.base, name);
    }
    return doesMatch;
  });
};

FileOperationCollection.prototype.run = function(taskFactory, opts) {
  opts = opts || {};
  if(opts.skip) {
    return this;
  }

  this.steps.push(function(stream) {
    return stream.pipe(taskFactory());
  });
  return this;
};

FileOperationCollection.prototype.runGulp = function(gulpTaskFactory, gulpTaskOpts, opts) {
  return this.run(function() {
    return gulpTaskFactory(gulpTaskOpts);
  }, opts);
};

var eatStream = function() {
  return through.obj(function(file, enc, cb) {
    cb(null);
  });
};

FileOperationCollection.prototype.put = function(dest) {
  var newDest = path.join(this.config.destDir, dest);
  this.steps.push(function(stream) {
    return stream
      .pipe(gulp.dest(newDest))
      .pipe(eatStream());
  });
  return this;
};


module.exports = function(cfg) {
  var config = Object.assign({}, defaultConfig, cfg);

  return {
    config: function(cfg) {
      config = Object.assign(config, cfg);
      return config;
    },
    pipes: [],
    filesIn: function(folder) {
      var newStream = new FileOperationCollection(folder);
      newStream.config = config;
      this.pipes.push(newStream);
      return newStream;
    },
    build: function() {
      return function() {
        var streams = this.pipes.map(function(task) {
          return task.steps.reduce(function(stream, step) {
            return step(stream);
          }, null).pipe(gulp.dest(config.destDir));
        });
        return merge(streams);
      }.bind(this);
    }
  };
};

import Moment from 'vendor/moment/moment.min';
import importantDate from 'modules/important-date';

document.querySelector('#birthday').textContent =
  Moment(importantDate).fromNow();

import cssLoader from 'modules/defer-css';
cssLoader();

import gulp from 'gulp';
import browserSync from 'browser-sync';

const defaultBrowserSyncConfig = {
  reloadOnRestart: true,
  open: false
};

export default function serve() {
  const options = Object.assign({}, defaultBrowserSyncConfig, {
    server: {
      baseDir: 'dist'
    }
  });
  const browserSyncInstance = browserSync.create();
  browserSyncInstance.init(options);

  gulp.watch('app/**/*', gulp.series('build'));
}

export default () => {
  window.requestAnimationFrame(() => {
    const lazyloads = document.querySelectorAll('noscript.lazyload');
    const container = document.createElement('div');
    [].forEach.call(lazyloads, lazyload => {
      const parent = lazyload.parentNode;
      container.innerHTML = lazyload.textContent;
      [].forEach.call(container.children, parent.appendChild.bind(parent));
    });
  });
};
